addresses_coordinates_pair.value:
("addresses"."latitude" is null and "addresses"."longitude" is null) or (
      "addresses"."latitude" between -90 and 90 and "addresses"."longitude" between -180 and 180
    )

orders_delivery_coordinates_pair.value:
("orders"."delivery_latitude" is null and "orders"."delivery_longitude" is null) or (
        "orders"."delivery_latitude" between -90 and 90 and "orders"."delivery_longitude" between -180 and 180
      )

